// Package json provides functions for marshaling and unmarshaling concrete Go
// values using Amino-compatible JSON encoding rules.
//
// Not all JSON emitted by Tendermint is generated by this package; some uses
// encoding/json instead for backwards compatibility.
//
// # Encoding rules
//
// The int, int64, uint, and uint64 types encode as decimal strings, preserving
// precision in consumers such as JavaScript. Smaller integer types encode as
// JSON numbers. Unmarshal requires the corresponding representation: an int64
// destination requires a JSON string, while an int32 destination requires a
// JSON number. Other scalars follow encoding/json.
//
// Byte slices and byte arrays encode as base64 strings: both []byte{1, 2, 3}
// and [3]byte{1, 2, 3} encode as "AQID". Other slices and arrays encode as JSON
// arrays, applying these rules recursively. Nil slices encode as null, empty
// non-nil slices as []; decoding an empty JSON array produces a nil slice.
//
// Maps require string keys, including named string types. Nil and empty maps
// both encode as {}, retaining Amino compatibility. Map iteration order is not
// specified. Structs support JSON field names, omitempty, and ignored fields;
// unexported fields are ignored. Custom encoding/json.Marshaler and
// encoding/json.Unmarshaler implementations are supported.
//
// Times encode in UTC using RFC3339Nano. Unmarshal requires a UTC timestamp
// ending in Z. A zero time encodes as "0001-01-01T00:00:00Z", and a nil pointer
// encodes as null.
//
// # Concrete values
//
// Marshal does not add type/value wrappers. Unmarshal requires a pointer to a
// concrete destination; it cannot select a concrete type for a non-null
// interface destination. The reflection codec also rejects interface-typed
// fields and collection elements. A top-level interface holding a concrete
// value can be passed to Marshal because its dynamic concrete type is used.
// JSON null can be decoded into an interface, setting it to nil. Custom JSON
// methods on concrete types can implement their own encoding and decoding.
//
// This complete example preserves a 64-bit integer and byte data without type
// registration:
//
//	package main
//
//	import (
//		"fmt"
//
//		"github.com/Sidiora-Labs/Paxeer-X-Network/consensus/libs/json"
//	)
//
//	func main() {
//		type Record struct {
//			Height int64  `json:"height"`
//			Data   []byte `json:"data"`
//		}
//		input := Record{Height: 9007199254740993, Data: []byte{1, 2, 3}}
//		wire, err := json.Marshal(input)
//		if err != nil {
//			panic(err)
//		}
//		var output Record
//		if err := json.Unmarshal(wire, &output); err != nil {
//			panic(err)
//		}
//		fmt.Println(string(wire))
//		fmt.Println(output.Height, output.Data)
//	}
//
// Output:
//
//	{"height":"9007199254740993","data":"AQID"}
//	9007199254740993 [1 2 3]
//
// Use MarshalIndent(value, "", "  ") for indented output with the same rules.
//
// # Tagged polymorphic values
//
// Code within the consensus tree that needs polymorphic type/value wrappers
// should use the separate package
// github.com/Sidiora-Labs/Paxeer-X-Network/consensus/internal/jsontypes. Its
// internal import restriction limits callers to the consensus tree. Concrete
// implementations provide TypeTag() string, register with jsontypes.MustRegister
// during initialization, and use jsontypes.Marshal and jsontypes.Unmarshal.
// Registration there does not change this package's behavior. The tagged
// codec uses encoding/json for the wrapped payload, so its integer rules differ
// from this package's rules. For example, this program belongs under consensus:
//
//	package main
//
//	import (
//		"fmt"
//
//		"github.com/Sidiora-Labs/Paxeer-X-Network/consensus/internal/jsontypes"
//	)
//
//	type Car struct {
//		Wheels int64 `json:"wheels"`
//	}
//
//	func (*Car) TypeTag() string { return "vehicle/car" }
//
//	func init() { jsontypes.MustRegister(&Car{}) }
//
//	func main() {
//		wire, err := jsontypes.Marshal(&Car{Wheels: 4})
//		if err != nil {
//			panic(err)
//		}
//		var output jsontypes.Tagged
//		if err := jsontypes.Unmarshal(wire, &output); err != nil {
//			panic(err)
//		}
//		fmt.Println(string(wire))
//		fmt.Println(output.(*Car).Wheels)
//	}
//
// Output:
//
//	{"type":"vehicle/car","value":{"wheels":4}}
//	4
package json
